'use strict';
window.TravelPlanner=(()=>{
function distance(a,b){const r=x=>x*Math.PI/180,t=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lng-a.lng)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(t),Math.sqrt(1-t))}
function routeLength(points,start){return points.reduce((n,p,i)=>n+distance(i?points[i-1]:start,p),0)}
function improve(points,start){let route=[...points];for(let pass=0;pass<6;pass++){let improved=false;for(let i=0;i<route.length-1;i++)for(let j=i+1;j<route.length;j++){const candidate=[...route.slice(0,i),...route.slice(i,j+1).reverse(),...route.slice(j+1)];if(routeLength(candidate,start)+1<routeLength(route,start)){route=candidate;improved=true}}if(!improved)break}return route}
const currencies={GB:'GBP',FR:'EUR',DE:'EUR',IT:'EUR',ES:'EUR',PT:'EUR',NL:'EUR',GR:'EUR',AT:'EUR',IE:'EUR',KR:'KRW',JP:'JPY',US:'USD',CA:'CAD',AU:'AUD',NZ:'NZD',CH:'CHF',TH:'THB',VN:'VND',CN:'CNY',TW:'TWD',HK:'HKD',SG:'SGD',IN:'INR',AE:'AED',TR:'TRY',MX:'MXN'};
function currency(country){return currencies[country]||null}
function details(p,country){
 const t=p.tags||{},type=t.amenity==='restaurant'?'Restaurant':t.amenity==='cafe'?'Café':t.tourism==='museum'?'Museum':t.tourism==='gallery'?'Gallery':t.historic==='castle'?'Castle':t.historic==='memorial'||t.historic==='monument'||t.tourism==='artwork'?'Monument':t.leisure==='park'||t.leisure==='garden'?'Walk':t.tourism==='viewpoint'?'Viewpoint':p.type||'Sight';
 const base={Museum:120,Gallery:90,Castle:120,Monument:15,Walk:60,Viewpoint:30,Restaurant:60,'Café':45,Sight:60};
 return{...p,type,duration:p.durationReviewed||p.source!=='OpenStreetMap'?p.duration||base[type]||60:base[type]||60,currency:p.currency||currency(country),priority:p.priority??(t.wikipedia?3:t.wikidata?2:type==='Museum'||type==='Castle'?1:0),bookingSuggested:p.bookingSuggested??(['Museum','Gallery','Castle'].includes(type)||t.reservation==='yes'||t.reservation==='required'),website:/^https?:\/\//.test(t.website||t['contact:website']||'')?(t.website||t['contact:website']):p.website,feeFree:t.fee==='no'||p.feeFree};
}
function budget(p,country){
 const c=p.currency||currency(country);
 if(p.budget?.kind==='listed'&&p.website)return p.budget;
 return{currency:c,low:null,high:null,kind:'unknown'};
}

const highlights=[
 {id:'london-national-gallery',name:'National Gallery',lat:51.5089,lng:-0.1283,type:'Gallery',duration:120,durationReviewed:true,priority:5,country:'GB',cost:0,currency:'GBP',budget:{currency:'GBP',low:0,high:0,kind:'listed'},bookingSuggested:true,website:'https://www.nationalgallery.org.uk/visiting/plan-your-visit',source:'Official visitor information'},
 {id:'london-british-museum',name:'British Museum',lat:51.5194,lng:-0.127,type:'Museum',duration:180,durationReviewed:true,priority:5,country:'GB',cost:0,currency:'GBP',budget:{currency:'GBP',low:0,high:0,kind:'listed'},bookingSuggested:true,website:'https://www.britishmuseum.org/visit',source:'Official visitor information'},
 {id:'london-tower',durationSource:'https://www.hrp.org.uk/tower-of-london/visit/faqs/',name:'Tower of London',lat:51.5081,lng:-0.0759,type:'Castle',duration:180,durationReviewed:true,priority:5,country:'GB',cost:37,currency:'GBP',budget:{currency:'GBP',low:37,high:37,kind:'listed'},bookingSuggested:true,website:'https://www.hrp.org.uk/tower-of-london/visit/',source:'Official visitor information'}
];
function plan({places,center,days,startHour=9,endHour=21,pace=1,country}){
if(!Number.isInteger(days)||days<1||days>30||!Number.isFinite(startHour)||!Number.isFinite(endHour)||startHour<6||endHour>23||endHour<=startHour||!Number.isFinite(pace)||pace<1||pace>2)throw Error('Choose valid days and a finish time after your start time.');
const seen=new Set(),remaining=places.filter(p=>{if(!p.id||seen.has(p.id)||!Number.isFinite(p.lat)||!Number.isFinite(p.lng)||Math.abs(p.lat)>90||Math.abs(p.lng)>180)return false;seen.add(p.id);return true}).map(p=>country?details(p,country):({...p})),result=[];
// ponytail: nearby-first walking estimates; use a routing service for street-level travel times.
for(let d=0;d<days;d++){
 const items=[],missing=[];let minutes=Math.round(startHour*60),previous=center;
 const finish=Math.round(endHour*60),slots=[{at:720,type:'Restaurant',duration:60,label:'Lunch'},{at:900,type:'Café',duration:45,label:'Café break'},{at:1080,type:'Restaurant',duration:75,label:'Dinner'}].filter(s=>s.at>=minutes&&s.at+s.duration<=finish);
 function add(chosen,label){remaining.splice(chosen.index,1);items.push({place:chosen.p,duration:chosen.finish-chosen.arrival,time:String(Math.floor(chosen.arrival/60)).padStart(2,'0')+':'+String(chosen.arrival%60).padStart(2,'0'),label});minutes=chosen.finish;previous=chosen.p}
 function options(type,until,at=minutes,duration){return remaining.map((p,index)=>{const travel=distance(previous,p),arrival=Math.max(at,minutes+Math.ceil(travel/1000/4.2*60),['Museum','Gallery','Castle'].includes(p.type)?600:0);return{p,index,travel,arrival,finish:arrival+(duration||Math.max(15,Math.round((p.duration||75)/15)*15))}}).filter(c=>(type?c.p.type===type:!['Restaurant','Café','Stay'].includes(c.p.type))&&c.finish<=until&&(!['Museum','Gallery','Castle'].includes(c.p.type)||c.finish<=1080)).sort((a,b)=>{const score=c=>c.travel+(items.at(-1)?.place.type===c.p.type?750:0)+(c.p.type==='Monument'?3500:0)-(c.p.priority||0)*900;return score(a)-score(b)})}
 for(const slot of [...slots,{at:finish}]){
  while(minutes<slot.at){const choices=options(null,slot.type==='Restaurant'?Math.min(finish-slot.duration-15,slot.at+90):slot.type?slot.at-15:slot.at);if(!choices.length)break;add(choices[0],'Sightseeing')}
  if(slot.type){const mealAt=Math.max(slot.at,minutes+15);if(mealAt+slot.duration>finish)continue;const nearby=options(slot.type,Math.min(finish,mealAt+slot.duration+30),mealAt,slot.duration).filter(c=>c.travel<=2500);if(nearby.length)add(nearby[0],slot.label);else{missing.push(slot.label);items.push({place:{id:'meal-'+d+'-'+slot.at,name:slot.label+' · Choose nearby',type:slot.type,lat:previous.lat,lng:previous.lng,cost:0,duration:slot.duration,pendingMeal:true,near:previous.name||''},time:String(Math.floor(mealAt/60)).padStart(2,'0')+':'+String(mealAt%60).padStart(2,'0'),duration:slot.duration,label:slot.label});minutes=mealAt+slot.duration+15}}
 }

 result.push({items,missing,distance:Math.round(routeLength(items.map(i=>i.place),center))});
}return result}

async function discover(center,country,food=false){const query=food?`[out:json][timeout:12];nwr(around:1000,${center.lat},${center.lng})[amenity~"^(restaurant|cafe)$"][name];out center tags 60;`:`[out:json][timeout:20];(nwr(around:6000,${center.lat},${center.lng})[tourism~"^(museum|attraction|gallery|viewpoint)$"][name];nwr(around:6000,${center.lat},${center.lng})[historic~"^(castle|monument|archaeological_site)$"][name]; );out center tags 200;`;let json;for(const endpoint of ['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter']){try{const response=await fetch(endpoint,{method:'POST',body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(food?7000:25000)});if(!response.ok)throw Error();json=await response.json();break}catch{}}if(!json)throw Error('Local place search is unavailable. Try again in a moment.');const names=new Set();return(json.elements||[]).flatMap(e=>{const lat=e.lat??e.center?.lat,lng=e.lon??e.center?.lon,name=e.tags?.['name:en']||e.tags?.name;if(!name||!Number.isFinite(lat)||!Number.isFinite(lng)||names.has(name.toLowerCase()))return[];names.add(name.toLowerCase());return[details({id:'osm-'+e.type+'-'+e.id,name,en:e.tags?.['name:en']||name,lat,lng,country,tags:e.tags, type:e.tags?.amenity==='restaurant'?'Restaurant':e.tags?.amenity==='cafe'?'Café':e.tags?.tourism==='museum'?'Museum':'Sight',cost:0,duration:e.tags?.amenity==='cafe'?45:e.tags?.tourism==='museum'?120:60,guide:'A researched story for this place is not available yet.',source:'OpenStreetMap',sourceUrl:'https://www.openstreetmap.org/'+e.type+'/'+e.id},country)]})}
async function addDining(days,country){
const used=new Set(days.flatMap(d=>d.items.filter(i=>!i.place.pendingMeal).map(i=>i.place.id)));const cache=new Map();
await Promise.all(days.flatMap(d=>d.items.filter(i=>i.place.pendingMeal).map(async i=>{const a=i.place,key=a.lat.toFixed(3)+','+a.lng.toFixed(3);if(!cache.has(key))cache.set(key,discover(a,country,true).catch(()=>[]));await cache.get(key)})));
for(const day of days){for(let index=0;index<day.items.length;index++){const item=day.items[index];if(!item.place.pendingMeal)continue;const anchor=item.place,next=day.items.slice(index+1).find(i=>!i.place.pendingMeal)?.place||anchor;const key=anchor.lat.toFixed(3)+','+anchor.lng.toFixed(3);if(!cache.has(key))cache.set(key,discover(anchor,country,true).catch(()=>[]));const found=await cache.get(key);const ranked=found.filter(p=>p.type===anchor.type&&!used.has(p.id)).sort((a,b)=>(distance(anchor,a)+distance(a,next))-(distance(anchor,b)+distance(b,next)));const clock=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};const previous=day.items[index-1],following=day.items[index+1];const choice=ranked.find(p=>{const walk=Math.ceil(distance(anchor,p)/70),onward=Math.ceil(distance(p,next)/70);return distance(anchor,p)<=700&&(!previous||clock(previous.time)+previous.duration+walk<=clock(item.time))&&(!following||clock(item.time)+item.duration+onward<=clock(following.time))});if(choice){item.place=choice;used.add(choice.id);day.missing=day.missing.filter(label=>label!==item.label)}else{const query=(anchor.type==='Café'?'cafes':'restaurants')+' near '+(anchor.near||anchor.lat+','+anchor.lng);anchor.searchUrl=(country==='KR'?'https://map.naver.com/p/search/':'https://www.google.com/maps/search/?api=1&query=')+encodeURIComponent(query);}}
}return days}
return{distance,routeLength,improve,plan,discover,addDining,details,budget,currency,highlights};})();
